using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders; using SalesManagement.Core.Models;
namespace SalesManagement.Postgres.Configurations;
public sealed class CustomerInquiryConfiguration : IEntityTypeConfiguration<CustomerInquiry> { public void Configure(EntityTypeBuilder<CustomerInquiry> b) { b.ConfigureEntity("customer_inquiries"); b.Property(x => x.InquiryNumber).HasMaxLength(20).IsRequired(); b.Property(x => x.Title).HasMaxLength(300).IsRequired(); b.Property(x => x.CustomerName).HasMaxLength(200).IsRequired(); b.Property(x => x.ContactName).HasMaxLength(100).IsRequired(); b.Property(x => x.ContactEmail).HasMaxLength(254); b.Property(x => x.Status).HasConversion<string>(); b.Property(x => x.Summary).HasMaxLength(4000).IsRequired(); b.HasIndex(x => x.InquiryNumber).IsUnique(); b.HasOne<Customer>().WithMany().HasForeignKey(x => x.CustomerId).OnDelete(DeleteBehavior.Restrict); b.HasOne<User>().WithMany().HasForeignKey(x => x.OwnerUserId).OnDelete(DeleteBehavior.Restrict); b.HasMany(x => x.Activities).WithOne().HasForeignKey(x => x.InquiryId).OnDelete(DeleteBehavior.Cascade); b.HasMany(x => x.Attachments).WithOne().HasForeignKey(x => x.InquiryId).OnDelete(DeleteBehavior.Cascade); } }
public sealed class InquiryActivityConfiguration : IEntityTypeConfiguration<InquiryActivity> { public void Configure(EntityTypeBuilder<InquiryActivity> b) { b.ConfigureEntity("inquiry_activities"); b.Property(x => x.Kind).HasConversion<string>(); b.Property(x => x.Body).HasMaxLength(4000).IsRequired(); b.HasOne<User>().WithMany().HasForeignKey(x => x.ActorId).OnDelete(DeleteBehavior.Restrict); } }
public sealed class InquiryAttachmentConfiguration : IEntityTypeConfiguration<InquiryAttachment> { public void Configure(EntityTypeBuilder<InquiryAttachment> b) { b.ConfigureEntity("inquiry_attachments"); b.Property(x => x.FileName).HasMaxLength(255).IsRequired(); b.Property(x => x.ContentType).HasMaxLength(150).IsRequired(); b.Property(x => x.Content).HasColumnType("bytea").IsRequired(); b.HasOne<User>().WithMany().HasForeignKey(x => x.UploadedBy).OnDelete(DeleteBehavior.Restrict); } }
public sealed class QuoteConfiguration : IEntityTypeConfiguration<Quote> { public void Configure(EntityTypeBuilder<Quote> b) { b.ConfigureEntity("quotes"); b.Property(x => x.QuoteNumber).HasMaxLength(20).IsRequired(); b.Property(x => x.CustomerName).HasMaxLength(200).IsRequired(); b.Property(x => x.Result).HasConversion<string>(); b.HasIndex(x => x.QuoteNumber).IsUnique(); b.HasOne<Customer>().WithMany().HasForeignKey(x => x.CustomerId).OnDelete(DeleteBehavior.Restrict); b.HasOne<CustomerInquiry>().WithMany().HasForeignKey(x => x.InquiryId).OnDelete(DeleteBehavior.Restrict); b.HasOne<User>().WithMany().HasForeignKey(x => x.OwnerUserId).OnDelete(DeleteBehavior.Restrict); b.HasMany(x => x.Revisions).WithOne().HasForeignKey(x => x.QuoteId).OnDelete(DeleteBehavior.Cascade); } }
public sealed class QuoteRevisionConfiguration : IEntityTypeConfiguration<QuoteRevision> { public void Configure(EntityTypeBuilder<QuoteRevision> b) { b.ConfigureEntity("quote_revisions"); b.Property(x => x.Status).HasConversion<string>(); b.Property(x => x.Currency).HasConversion<string>(); b.Property(x => x.TradeType).HasConversion<string>(); b.Property(x => x.TaxType).HasConversion<string>(); foreach (var name in new[] { nameof(QuoteRevision.DiscountAmount), nameof(QuoteRevision.ShippingAmount), nameof(QuoteRevision.OtherAmount), nameof(QuoteRevision.SubtotalAmount), nameof(QuoteRevision.SupplyAmount), nameof(QuoteRevision.TaxAmount), nameof(QuoteRevision.TotalAmount) }) b.Property<decimal>(name).HasPrecision(20, 4); b.HasIndex(x => new { x.QuoteId, x.RevisionNumber }).IsUnique(); b.HasMany(x => x.Lines).WithOne().HasForeignKey(x => x.RevisionId).OnDelete(DeleteBehavior.Cascade); b.HasMany(x => x.Approvals).WithOne().HasForeignKey(x => x.RevisionId).OnDelete(DeleteBehavior.Cascade); b.HasMany(x => x.Dispatches).WithOne().HasForeignKey(x => x.RevisionId).OnDelete(DeleteBehavior.Cascade); } }
public sealed class QuoteLineConfiguration : IEntityTypeConfiguration<QuoteLine> { public void Configure(EntityTypeBuilder<QuoteLine> b) { b.ConfigureEntity("quote_lines"); b.Property(x => x.Description).HasMaxLength(500).IsRequired(); b.Property(x => x.Quantity).HasPrecision(20, 4); b.Property(x => x.UnitPrice).HasPrecision(20, 4); b.Property(x => x.Amount).HasPrecision(20, 4); b.HasOne<Product>().WithMany().HasForeignKey(x => x.ProductId).OnDelete(DeleteBehavior.Restrict); } }
public sealed class QuoteApprovalConfiguration : IEntityTypeConfiguration<QuoteApproval> { public void Configure(EntityTypeBuilder<QuoteApproval> b) { b.ConfigureEntity("quote_approvals"); b.Property(x => x.Decision).HasConversion<string>(); b.HasOne<User>().WithMany().HasForeignKey(x => x.RequestedBy).OnDelete(DeleteBehavior.Restrict); b.HasOne<User>().WithMany().HasForeignKey(x => x.DecidedBy).OnDelete(DeleteBehavior.Restrict); } }
public sealed class QuoteDispatchConfiguration : IEntityTypeConfiguration<QuoteDispatch> { public void Configure(EntityTypeBuilder<QuoteDispatch> b) { b.ConfigureEntity("quote_dispatches"); b.Property(x => x.Language).HasConversion<string>(); b.Property(x => x.Memo).HasMaxLength(2000); b.HasOne<User>().WithMany().HasForeignKey(x => x.RecordedBy).OnDelete(DeleteBehavior.Restrict); } }
public sealed class IncotermConfiguration : IEntityTypeConfiguration<Incoterm> { public void Configure(EntityTypeBuilder<Incoterm> b) { b.ConfigureEntity("incoterms"); b.Property(x => x.Code).HasMaxLength(3).IsRequired(); b.Property(x => x.DisplayName).HasMaxLength(150).IsRequired(); b.Property(x => x.Status).HasConversion<string>(); b.HasIndex(x => x.Code).IsUnique(); } }
public sealed class QuoteNumberSequenceConfiguration : IEntityTypeConfiguration<QuoteNumberSequence> { public void Configure(EntityTypeBuilder<QuoteNumberSequence> b) { b.ToTable("quote_number_sequences"); b.HasKey(x => new { x.Year, x.Month, x.Kind }); b.Property(x => x.Kind).HasMaxLength(20); } }
